Given an integer array arr[] and an integer k, find the total number of contiguous subarrays whose sum is divisible by k.Examples: Input: arr[] = [4, 5, 0, -2, -3, 1], k = 5Output: 7Explanation: There are 7 subarrays whose sum is divisible by 5: [4, 5, 0, -2, -3, 1], [5], [5, 0], [5, 0, -2, -3], [0], [0, -2, -3] and [-2, -3].Input: arr[] = [2, 2, 2, 2, 2, 2], k = 2Output: 21Explanation: All subarray sums are divisible by 2.Input: arr[] = [-1, -3, 2], k = 5Output: 0Explanation: There is no subarray whose sum is divisible by 5.Try It YourselfTable of Content[Naive Approach] - Iterating over all subarrays - O(n^2) time and O(1) space[Expected Approach] - Using Prefix Sum modulo k [Naive Approach] - Iterating over all subarrays - O(n2) time and O(1) spaceThe idea is to iterate over all possible subarrays while maintaining their sum. Whenever the sum is divisible by k, increment the count.
            C++

    #include <iostream>
#include <vector>

using namespace std;

int subCount(vector<int> &arr, int k) {
	int n = arr.size(), res = 0;	

	// Iterating over starting indices of subarray
	for(int i = 0; i < n; i++) {
    	int sum = 0;

		// Iterating over ending indices of subarray
        for(int j = i; j < n; j++) {
        	sum = (sum + arr[j]) % k;
            if(sum == 0)
                res += 1;
        }
    }
	return res;
}

int main() {
	vector<int> arr = {4, 5, 0, -2, -3, 1};
    int k = 5;

    cout << subCount(arr, k);
}


