Output7[Expected Approach] - Using Prefix Sum modulo k The idea is to use Prefix Sum Technique along with Hashing. On observing carefully, we can say that if a subarray arr[i...j] has sum divisible by k, then (prefix sum[i] % k) will be equal to the (prefix sum[j] % k). So, we can iterate over arr[] while maintaining a hash map or dictionary to count the number of (prefix sum mod k). For each index i, the number of subarrays ending at i and having sum divisible by k will be equal to the count of occurrences of (prefix sum[i] mod k) before i.Note: Negative value of (prefix sum mod k) needs to be handled separately in languages like C++, Java, C# and JavaScript, whereas in Python (prefix sum mod k) is always a non-negative value as it takes the sign of the divisor, that is k.
            C++

    #include <iostream>
#include <vector>
#include <unordered_map>
using namespace std;

int subCount(vector<int> &arr, int k) {
	int n = arr.size(), res = 0;
	unordered_map<int, int> prefCnt;
	int sum = 0;

	for(int i = 0; i < n; i++) {

    	// prefix sum mod k (handling negative prefix sum)
    	sum = ((sum + arr[i]) % k + k) % k;

        // If sum == 0, then increment the result by 1
		// to count subarray arr[0...i]
        if(sum == 0)
        	res += 1;

        // Add count of all starting points for index i
		res += prefCnt[sum];

        prefCnt[sum] += 1;
    }
	return res;
}

int main() {
	vector<int> arr = {4, 5, 0, -2, -3, 1};
    int k = 5;

    cout << subCount(arr, k);
}


